<?php
require __DIR__.'/../vendor/autoload.php';$app=require __DIR__.'/../bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
$users=App\Models\User::with(['roles.permissions','department.permissions','permissionOverrides','campuses'])->where('status',1)->get();$rows=[];
foreach($users as $u){if($u->roles->contains('code','super-admin'))continue;$codes=$u->roles->where('status',1)->flatMap(fn($r)=>$r->permissions->pluck('code'))->merge($u->department?->permissions->pluck('code')??[])->merge($u->permissionOverrides->where('pivot.allowed',true)->pluck('code'))->unique();if(!$codes->contains('reports.view'))continue;$tabs=App\Support\AcademicReportPermissions::visibleTypes($u);$rows[]=['user_id'=>$u->id,'active_campus'=>$u->active_campus_id,'global'=>$u->is_global,'assigned_campuses'=>$u->campuses->modelKeys(),'role_campuses'=>$u->roles->map(fn($r)=>['role_id'=>$r->id,'campus_id'=>$r->pivot->campus_id,'global'=>$r->is_global])->all(),'configured_report_tabs'=>$codes->filter(fn($c)=>str_starts_with($c,'reports.')&&str_ends_with($c,'.view'))->count(),'visible_report_tabs'=>count($tabs)];}echo json_encode($rows,JSON_PRETTY_PRINT);
